var allKeywords = new Set();
var allLocations = new Set();
var activeFilters = [];

imageList.sort(function(a, b) {
	if(a.CreateDate < b.CreateDate) {return 1;}
	if(a.CreateDate > b.CreateDate) {return -1;}
	return 0;
});

imageList.forEach(image => {
	
	image.Subject.forEach(keyword => {
		allKeywords.add(keyword);
	});
	
	allLocations.add(image.Location);
});

[...allKeywords]
	.sort((a,b) => a.localeCompare(b))
	.forEach(keyword => {
	
		addFilterItem(
			"keywordList",
			keyword
		);
});

[...allLocations]
	.sort((a,b) => a.localeCompare(b))
	.forEach(location => {
	
		addFilterItem(
			"locationList",
			location
		);
});

document.querySelectorAll("#mySidenav input")
	.forEach(input => {
	
	input.addEventListener("change", renderGallery);
});


renderGallery();

function createGalleryItem(item) {
	
	var galleryItem = document.createElement("a");
	
	galleryItem.className = "gallery-item";
	
	var ratio = item.ImageWidth / item.ImageHeight;
	
	if (ratio < 0.85) {
      galleryItem.classList.add("portrait");
    } else if (ratio < 1.15) {
      galleryItem.classList.add("square");
    } else if (ratio < 2.2) {
      galleryItem.classList.add("landscape");
    } else {
      galleryItem.classList.add("ultrawide");
    }
	
	galleryItem.innerHTML = `
		<img
			src="images/grid/${item.name}_800.avif"
			width="${item.ImageWidth}"
			height="${item.ImageHeight}"
			srcset="
				images/grid/${item.name}_400.avif 400w,
				images/grid/${item.name}_800.avif 800w,
				images/grid/${item.name}_1200.avif 1200w,
				images/full/${item.name}_Full.avif 2560w
			"
		>
		
		<div class="image-border">
			<div class="frame-top">
				<span class="borderTitle">${item.Title}</span>
			</div>

			<div class="frame-bottom">
				<span class="borderDate">${formatPhotoDate(item.CreateDate)}</span>
				<span class="borderLocation">ðŸ“ ${item.Location}</span>
			</div>
		</div>

	`;
	
	galleryItem.addEventListener("click", () => {
		openOverlay(item);
	});
	
	return galleryItem;
}

function renderGallery() {
	
	var gallery = document.getElementById("gallery");
	
	var selectedKeywords = [
		
		...document.querySelectorAll(
			"#keywordList input:checked"
		)
	].map(cb => cb.value);
	
	var selectedLocations = [
		
		...document.querySelectorAll(
			"#locationList input:checked"
		)
	].map(cb => cb.value);
	
	
	
	var filteredImages = imageList.filter(image => {
		
		var keywordMatch = 
			
			selectedKeywords.length == 0 ||
			
			selectedKeywords.every(keyword =>  //AND Logic
			//selectedKeywords.some(keyword => //OR Logic for Keyword selection
								   
				image.Subject.includes(keyword)
								   
			);
		
		var locationMatch = 
			
			selectedLocations.length == 0 ||
			
			selectedLocations.includes(image.Location);
		
		return (
			keywordMatch && locationMatch
		);
		
	});
	
	gallery.innerHTML = "";
	
	filteredImages.forEach(image => {
		
		var item = createGalleryItem(image);
		
		gallery.appendChild(item);
		
	});
	
	$("#gallery").justifiedGallery({
		rowHeight: 300,
		maxRowHeight: 500,
		margins: 12,
		border: 0,
		lastRow: "nojustify",
		captions: false,
		waitThumbnailsLoad: true
	}).on('jg.complete', function () {
		applyAccurateSizes();
	});
	
}

function addFilterItem(listId, value) {
	
	var li = document.createElement("li");
	
	li.innerHTML = `
		<label class="filterLabel">
			
			<input
				type="checkbox"
				value="${value}"
			>

			<span
				class="filterText"
				title="${value}"
			>

			${value}

		</label>

	`;
	
	document.getElementById(listId).appendChild(li)
}

function openOverlay(selectedImg) {
	
	var lightbox = document.getElementById("lightbox");
	var lightboxCard = document.querySelector(".lightbox-card");
	var lightboxImg = document.getElementById("lightbox-img");
	var lightboxText = document.getElementById("lightbox-text");
	var lightboxTitle = document.getElementById("lightbox-title");
	var mapFrame = document.getElementById("lightbox-map-frame");
	
	lightbox.addEventListener("click", (e) => {
		if (e.target == lightbox) {
			lightbox.classList.remove("active");
		}
	});
	
	document.addEventListener("keydown", (e) => {
		if (e.key == "Escape") {
			lightbox.classList.remove("active");
		}
	});
	
	lightboxImg.src = "";
	lightboxCard.classList.remove("portrait");
	mapFrame.src = "";
	
	lightboxTitle.textContent = selectedImg.Title;
	lightboxText.textContent = selectedImg.Description;
	
	var lat = selectedImg.GPSLatitude * ((selectedImg.GPSLatitudeRef == "N") ? 1 : -1);
	var lng = selectedImg.GPSLongitude * ((selectedImg.GPSLongitudeRef == "E") ? 1 : -1);
	
	mapFrame.src = "https://www.google.com/maps/embed/v1/place?key=AIzaSyA-7lgcuYOldRXBEDS4f_YV7Lyp8Ly-Bxk&&q=" + lat + "," + lng + "&zoom=12";
	
	if (selectedImg.ImageHeight > selectedImg.ImageWidth) {
		lightboxCard.classList.add("portrait");
	}
	
	lightboxImg.src = "images/full/" + selectedImg.name + "_full.avif";
	
	lightbox.classList.add("active");
	
}

function formatPhotoDate(dateString) {

  // Convert EXIF format to ISO-like format
  const fixed = dateString
    .replace(/^(\d{4}):(\d{2}):(\d{2})/, "$1-$2-$3")
    .replace(" ", "T");

  const date = new Date(fixed);

  return date.toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric"
  });
}

function toggleSideNav() {
	var sideNav = document.getElementById("mySidenav");
	var gallery = document.getElementById("gallery");
	var filterBtn = document.getElementById("filterBtn");
	
	if(sideNav.classList.contains("sideHidden")) {
		
		sideNav.classList.remove("sideHidden");
		sideNav.classList.add("sideVisible");
		gallery.classList.add("galleryShifted");
		filterBtn.classList.add("active");
	}
	
	else {
		
		sideNav.classList.add("sideHidden");
		sideNav.classList.remove("sideVisible");
		gallery.classList.remove("galleryShifted");
		filterBtn.classList.remove("active");
	}
}

function applyAccurateSizes() {

  document.querySelectorAll("#gallery img").forEach(img => {

    const container = img.parentElement;

    const width = container.getBoundingClientRect().width;

    img.sizes = `${Math.ceil(width)}px`;

  });

}

